import EventEmitter from 'eventemitter3';
import { PageVisibilityEvents } from './types';

export class PageVisibility extends EventEmitter<PageVisibilityEvents> {
    private mIsVisible: boolean;
    private set isVisible(value: boolean) { this.mIsVisible = value; }
    public get isVisible(): boolean { return this.mIsVisible; }

    constructor() {
        super();
        this.mIsVisible = document.visibilityState === 'visible';

        window.addEventListener('visibilitychange', () => {
            this.isVisible = document.visibilityState === 'visible';
            this.emit('visibilityChanged', this.isVisible);
        });
    }
}
